/**
 * Lifecycle states for personal data export jobs.
 *
 * - Pending: job accepted and queued
 * - Processing: content is being prepared
 * - Ready: artifact prepared and optionally downloadable via signed URI
 * - Expired: artifact retention window elapsed; regeneration required
 * - Failed: job encountered an unrecoverable error
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IEPersonalDataExportStatus =
  | "pending"
  | "processing"
  | "ready"
  | "expired"
  | "failed";
